#include <array>
#include <algorithm>
#include <cassert>
#include <cstdio>
#include <cstdint>
#include <map>
#include <tuple>
#include <vector>
int main(){FILE*f=fopen("general_census.csv","w"),*v=fopen("general_verification.csv","w");fprintf(f,"n,hamiltonian_paths,absent_pairs,reciprocal_pairs,strong,labelled_count\n");fprintf(v,"n,enumerated_graphs,target_graphs,direct_target_checks,support_hypergraph_checks\n");for(int n=1;n<=5;n++){int pairs=n*(n-1)/2,total=1<<(2*pairs),N=1<<n;std::map<std::tuple<int,int,int,bool>,long long>counts;std::vector<std::vector<int>>perms;std::vector<int>p(n);for(int i=0;i<n;i++)p[i]=i;do{perms.push_back(p);}while(std::next_permutation(p.begin(),p.end()));long long targets=0,supportchecks=0;for(int code=0;code<total;code++){int z=code,in[5]={},out[5]={},absent=0,reciprocal=0;uint32_t E=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){int s=z&3;z>>=2;absent+=s==0;reciprocal+=s==3;if(s&1){out[i]|=1<<j;in[j]|=1<<i;E|=1u<<(i*n+j);}if(s&2){out[j]|=1<<i;in[i]|=1<<j;E|=1u<<(j*n+i);}}uint16_t dp[32][5]={};for(int j=0;j<n;j++)dp[1<<j][j]=1;for(int s=1;s<N;s++)for(int js=s;js;js&=js-1){int j=__builtin_ctz((unsigned)js),prior=s^(1<<j);if(!prior)continue;for(int is=prior&in[j];is;is&=is-1)dp[s][j]+=dp[prior][__builtin_ctz((unsigned)is)];}int h=0;for(int j=0;j<n;j++)h+=dp[N-1][j];if(h!=7&&h!=21)continue;targets++;int reach=1;for(int k=0;k<n;k++){int r=reach;for(int s=reach;s;s&=s-1)r|=out[__builtin_ctz((unsigned)s)];reach=r;}bool strong=reach==N-1;reach=1;for(int k=0;k<n;k++){int r=reach;for(int s=reach;s;s&=s-1)r|=in[__builtin_ctz((unsigned)s)];reach=r;}strong&=reach==N-1;counts[{h,absent,reciprocal,strong}]++;int hd=0;uint32_t U=0;std::vector<uint32_t>yes,no;for(auto p:perms){uint32_t edges=0;for(int i=0;i<n-1;i++)edges|=1u<<(p[i]*n+p[i+1]);bool ok=(edges&E)==edges;hd+=ok;if(ok){U|=edges;yes.push_back(edges);}else no.push_back(edges);}assert(hd==h);if(n==4&&h==7){supportchecks++;int hu=0;for(auto edges:yes)hu+=(edges&U)==edges;for(auto edges:no)hu+=(edges&U)==edges;assert(hu==h);uint32_t X=E&~U;for(auto edges:no){uint32_t forbidden=edges&~U;assert(forbidden);assert((forbidden&X)!=forbidden);}
// Stronger converse: exhaust every extension X of this support U.
uint32_t universe=0;for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(i!=j)universe|=1u<<(i*n+j);uint32_t available=universe&~U;for(uint32_t x=available;;x=(x-1)&available){bool independent=true;for(auto edges:no){auto forbidden=edges&~U;if((forbidden&x)==forbidden){independent=false;break;}}uint32_t candidate=U|x;int actual=0;for(auto p:perms){bool ok=true;for(int i=0;i<n-1;i++)if(!(candidate>>(p[i]*n+p[i+1])&1)){ok=false;break;}actual+=ok;}assert(independent==(actual==h));if(x==0)break;}}
}for(auto [key,count]:counts){auto[h,a,r,s]=key;fprintf(f,"%d,%d,%d,%d,%d,%lld\n",n,h,a,r,s,count);}fprintf(v,"%d,%d,%lld,%lld,%lld\n",n,total,targets,targets,supportchecks);printf("n=%d total=%d targets=%lld support=%lld\n",n,total,targets,supportchecks);}fclose(f);fclose(v);}
